                vp += [k for k, x, y in neo if x != y and (not (k == 'neo_attempt' and 'attempt_kieu' in vp))]
        else:
            vp += [f'mien:{x}' for x in mod.kiem_mien(ng['chuoi'], cay / dd, m_c)]
    if not vp:
